        }
        var reqData = ref = {
            "CommonData": comRefData,
            "dmSearchLoop": {
                "svcLoopCd": "PS2",
                "skdDirCd": "W"
            }
        };
        //$p.executeSubmission( "submission1", reqData );
        var subOpt = {
            id: "submission2",
            target: "data:json,{'id':'dlPopCobList2','key':'dlPopCobList'}",
            mode: "asyncronous",
            action: "./gridView_submission_selectbox_WEFF-772_(WSQ-4113).json",
            method: "post",
            mediatype: "application/json",
            encoding: "UTF-8"
        };
        scwin.dynamicSubmission(subOpt, reqData);
    }
};
scwin.dynamicSubmission = function(option, req) {
    var submissionObj = option;
    $p.createSubmission(submissionObj);
    $p.executeSubmission("submission2", req);
};
