scwin.checkVal1 = function() {
    var select_width = WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id + 'gridView1_cell_1_5')).width();
    var select_table_width = parseInt(WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___selectbox_col106_itemTable').style.width) + 5;
    return select_table_width > select_width
}
scwin.checkVal2 = function() {
    var select_width = WebSquare.wUnit.getJq(WebSquare.wUnit.getDomById($p.id + 'gridView1_cell_1_5')).width();
    var select_table_width = parseInt(WebSquare.wUnit.getDomById('G_'+$p.id+'gridView1___autoComplete_1_col112_col112_itemTable').style.width) + 5;
    return select_table_width > select_width
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "1000");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_1_5').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('gridBodyDefault_autoComplete_div_img')[1].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
